# Reuse artwork already embedded from the images the user uploaded.
match=re.search(r'\.analysis-art\{[^}]*background-image:linear-gradient\([^;]*?url\("(data:image/webp;base64,[^"]+)"\)',s)
# The CSS block may be minified with other declarations; extract URL from .analysis-art rule more robustly.
if not match:
    m=re.search(r'\.analysis-art[^}]*url\("(data:image/webp;base64,[^"]+)"\)',s)
    if not m: raise SystemExit('Could not find embedded reference illustration')
    art=m.group(1)
else: art=match.group(1)

