s=s.replace("renderTariff(6);", "renderTariff(6);persistMission();",1)

# replace main tab selection for quiz and missions; ensure detail return takes you back to mypage but active tab remains appropriate.
# Add document initialization after scripts.
out=Path('/home/user/output/polar_home_snow_mission_demo.html')
out.write_text(s,encoding='utf-8')
